class Solution {
  public List<Integer> findGoodIntegers(int n) {
    java.util.HashMap<Long, Integer> count = new java.util.HashMap<>();
    for (long a = 1; a * a * a <= n; a++) {
      for (long b = a; a * a * a + b * b * b <= n; b++)
        count.merge(a * a * a + b * b * b, 1, Integer::sum);
    }
    List<Integer> res = new ArrayList<>();
    for (java.util.Map.Entry<Long, Integer> e : count.entrySet())
      if (e.getValue() >= 2) res.add((int) (long) e.getKey());
    java.util.Collections.sort(res);
    return res;
  }
}
